#include <iostream>

class Account {
public:
    void deposit(int n) { balance_ += n; }
    bool withdraw(int n) {
        if (n > balance_) return false;
        balance_ -= n;
        return true;
    }
    int balance() const { return balance_; }
private:
    int balance_ = 0;
};

int main() {
    Account a;
    a.deposit(100);
    std::cout << a.withdraw(150) << " " << a.balance() << "\n";
    return 0;
}

